    k_death = log(2) / (t_half_h * 60.0)
    thickness_mm = inputs["section_thickness_um"] / 1000.0
    rho = q * CD8_C / k_death / 1000.0
    d_2d = rho * thickness_mm
    return d_2d  # cells/mm^2
end

