# ======================================================================
# JOINT TURING MODEL
# ======================================================================
@model function joint_calibration(data)
    # =========================================
    # PRIORS (shared across targets)
    # =========================================
    N_IL2_CD4 ~ Normal(8.0, 2.0)  # Used by: N_IL2_CD4_division_destiny_Gett1998
    N_IL2_CD8 ~ Normal(5.0, 2.0)  # Used by: N_IL2_CD8_division_generations_castro2012
    k_C1_growth ~ LogNormal(-5.0, 1.0)  # Used by: k_C1_growth_pdac_human_vdt_ahn2017, k_C1_growth_pdac_tumor_doubling_jang2015
    k_CCL2_sec ~ LogNormal(-20.64, 2.5)  # Used by: k_CCL2_sec_Fujita2010_PrSC, k_CCL2_sec_Steube1999_proxy, k_CCL2_sec_bcproxy_yoshimura2023, k_CCL2_sec_psc_michalski2008, k_CCL2_sec_pdac_plasma_Nixon2013
    k_CCL2_deg ~ LogNormal(1.94, 0.3)  # Used by: k_CCL2_sec_pdac_plasma_Nixon2013
    k_M1_pol ~ LogNormal(0.0, 3.4)  # Used by: k_M1_pol_Watkins2007_IL12_TAM_reprogramming, k_M1_pol_repolarization_horhold2020, k_M1_pol_rp182_m2_to_m1_repolarization, k_M1_pol_pdac_cd86_cd163_gu2023, k_M1_pol_steady_state_ratio_DLBCL2021, k_M1_pol_pdac_m1m2ratio_DeSimoni2023, k_M1_pol_tam_ratio_herwig2013, k_Mac_rec_humanPDAC_CD40_2021
    k_M2_pol ~ LogNormal(0.0, 3.4)  # Used by: k_M1_pol_pdac_cd86_cd163_gu2023, k_M1_pol_steady_state_ratio_DLBCL2021, k_M1_pol_pdac_m1m2ratio_DeSimoni2023, k_M1_pol_tam_ratio_herwig2013, k_Mac_rec_humanPDAC_CD40_2021
    k_MDSC_rec ~ LogNormal(17.44, 2.5)  # Used by: k_MDSC_rec_recruitment_pericyte_MDSC_Hong2015, k_MDSC_rec_oscc_ccl2_oo2022, k_MDSC_rec_PDAC_Porembka2012, k_MDSC_rec_panc02_spleenexpansion_ghansah2013, k_MDSC_rec_pdac_trovato2019, k_MDSC_rec_panc02_tnfr1_chopra2013
    k_MDSC_death ~ LogNormal(0.0, 1.5)  # Used by: k_MDSC_rec_PDAC_Porembka2012, k_MDSC_rec_pdac_trovato2019, k_MDSC_rec_panc02_tnfr1_chopra2013
    k_Mac_rec ~ LogNormal(13.89, 1.5)  # Used by: k_Mac_rec_PDAC_M1_recruitment_Gu2023, k_Mac_rec_PDAC_TAM_recruitment_Chen2015
    k_Mac_death ~ LogNormal(-3.91, 1.0)  # Used by: k_Mac_rec_PDAC_M1_recruitment_Gu2023, k_Mac_rec_PDAC_TAM_recruitment_Chen2015
    k_apsc_death ~ LogNormal(-2.65, 1.7)  # Used by: k_apsc_death_melatoninPSC_Estaras2021, k_apsc_death_RA_Xiao2015, k_apsc_death_hsc_apoptosis_issa2001
    k_psc_activation ~ LogNormal(-0.693, 1.0)  # Used by: k_psc_activation_apte1998
    n_CD8_clones ~ LogNormal(2.3, 1.0)  # Used by: n_CD8_clones_Meng2023_PDAC
    q_CD8_T_in ~ LogNormal(-8.0, 3.4)  # Used by: q_CD8_T_in_extravasation_boissonnas2007, q_CD8_T_in_yorty2007_sv11_brain_tumor, q_CD8_T_in_PDAC_CD8density_ModPathol2019
    k_CD8_death ~ LogNormal(0.0, 1.0)  # Used by: q_CD8_T_in_PDAC_CD8density_ModPathol2019
    cd8_exclusion_fraction ~ Uniform(0.7, 0.99)  # Used by: q_CD8_T_in_PDAC_CD8density_ModPathol2019
    q_Treg_T_in ~ LogNormal(-7.0, 2.0)  # Used by: q_Treg_T_in_Tremblay2017_MRIcelltracking, q_Treg_T_in_PDAC_Tang2014, q_Treg_T_in_extravasation_PDAC, q_Treg_T_in_Jiang2014_Liyanage2002
    k_Treg_death ~ LogNormal(-2.3, 1.0)  # Used by: q_Treg_T_in_Jiang2014_Liyanage2002

    # =========================================
    # LIKELIHOODS
    # =========================================

    # N_IL2_CD4_division_destiny_Gett1998
    params_N_IL2_CD4_division_destiny_Gett1998 = Dict("N_IL2_CD4" => N_IL2_CD4)
    inputs_N_IL2_CD4_division_destiny_Gett1998 = data["N_IL2_CD4_division_destiny_Gett1998"].inputs
    pred_N_IL2_CD4_division_destiny_Gett1998 = compute_N_IL2_CD4_division_destiny_Gett1998(params_N_IL2_CD4_division_destiny_Gett1998, inputs_N_IL2_CD4_division_destiny_Gett1998)
    data["N_IL2_CD4_division_destiny_Gett1998"].obs_median[1] ~ Normal(pred_N_IL2_CD4_division_destiny_Gett1998, data["N_IL2_CD4_division_destiny_Gett1998"].obs_sigma[1])

    # N_IL2_CD8_division_generations_castro2012
    params_N_IL2_CD8_division_generations_castro2012 = Dict("N_IL2_CD8" => N_IL2_CD8)
    inputs_N_IL2_CD8_division_generations_castro2012 = data["N_IL2_CD8_division_generations_castro2012"].inputs
    pred_N_IL2_CD8_division_generations_castro2012 = compute_N_IL2_CD8_division_generations_castro2012(params_N_IL2_CD8_division_generations_castro2012, inputs_N_IL2_CD8_division_generations_castro2012)
    data["N_IL2_CD8_division_generations_castro2012"].obs_median[1] ~ Normal(pred_N_IL2_CD8_division_generations_castro2012, data["N_IL2_CD8_division_generations_castro2012"].obs_sigma[1])
    data["N_IL2_CD8_division_generations_castro2012"].obs_median[2] ~ Normal(pred_N_IL2_CD8_division_generations_castro2012, data["N_IL2_CD8_division_generations_castro2012"].obs_sigma[2])

    # k_C1_growth_pdac_human_vdt_ahn2017
    params_k_C1_growth_pdac_human_vdt_ahn2017 = Dict("k_C1_growth" => k_C1_growth)
    inputs_k_C1_growth_pdac_human_vdt_ahn2017 = data["k_C1_growth_pdac_human_vdt_ahn2017"].inputs
    pred_k_C1_growth_pdac_human_vdt_ahn2017 = compute_k_C1_growth_pdac_human_vdt_ahn2017(params_k_C1_growth_pdac_human_vdt_ahn2017, inputs_k_C1_growth_pdac_human_vdt_ahn2017)
    data["k_C1_growth_pdac_human_vdt_ahn2017"].obs_median[1] ~ LogNormal(log(pred_k_C1_growth_pdac_human_vdt_ahn2017), data["k_C1_growth_pdac_human_vdt_ahn2017"].obs_sigma[1])

    # k_C1_growth_pdac_tumor_doubling_jang2015
