# Plot marginal posteriors with priors
println("\nPlotting marginal posteriors...")

param_names = [:N_IL2_CD4, :N_IL2_CD8, :k_C1_growth, :k_CCL2_sec, :k_CCL2_deg, :k_M1_pol, :k_M2_pol, :k_MDSC_rec, :k_MDSC_death, :k_Mac_rec, :k_Mac_death, :k_apsc_death, :k_psc_activation, :n_CD8_clones, :q_CD8_T_in, :k_CD8_death, :cd8_exclusion_fraction, :q_Treg_T_in, :k_Treg_death]
param_labels = ["N_IL2_CD4", "N_IL2_CD8", "k_C1_growth", "k_CCL2_sec", "k_CCL2_deg", "k_M1_pol", "k_M2_pol", "k_MDSC_rec", "k_MDSC_death", "k_Mac_rec", "k_Mac_death", "k_apsc_death", "k_psc_activation", "n_CD8_clones", "q_CD8_T_in", "k_CD8_death", "cd8_exclusion_fraction", "q_Treg_T_in", "k_Treg_death"]

priors = Dict(
    :N_IL2_CD4 => Normal(8.0, 2.0),
    :N_IL2_CD8 => Normal(5.0, 2.0),
    :k_C1_growth => LogNormal(-5.0, 1.0),
    :k_CCL2_sec => LogNormal(-20.64, 2.5),
    :k_CCL2_deg => LogNormal(1.94, 0.3),
    :k_M1_pol => LogNormal(0.0, 3.4),
    :k_M2_pol => LogNormal(0.0, 3.4),
    :k_MDSC_rec => LogNormal(17.44, 2.5),
    :k_MDSC_death => LogNormal(0.0, 1.5),
    :k_Mac_rec => LogNormal(13.89, 1.5),
    :k_Mac_death => LogNormal(-3.91, 1.0),
    :k_apsc_death => LogNormal(-2.65, 1.7),
    :k_psc_activation => LogNormal(-0.693, 1.0),
    :n_CD8_clones => LogNormal(2.3, 1.0),
    :q_CD8_T_in => LogNormal(-8.0, 3.4),
    :k_CD8_death => LogNormal(0.0, 1.0),
    :cd8_exclusion_fraction => Uniform(0.7, 0.99),
    :q_Treg_T_in => LogNormal(-7.0, 2.0),
    :k_Treg_death => LogNormal(-2.3, 1.0)
)

plots = []
for (i, pname) in enumerate(param_names)
    samples = vec(chain[pname])
    med = median(samples)
    ci_lo = quantile(samples, 0.05)
    ci_hi = quantile(samples, 0.95)

    # X range based on posterior samples
    xmin, xmax = quantile(samples, 0.001), quantile(samples, 0.999)
    xrange = range(xmin, xmax, length=200)

    # Prior density
    prior_dist = priors[pname]
    prior_pdf = pdf.(prior_dist, xrange)

    # Start with prior (gray, underneath)
    plt = plot(xrange, prior_pdf;
        fill=true, fillalpha=0.2, color=:gray, linewidth=1, linecolor=:gray,
        xlabel=param_labels[i], ylabel="",
        label="Prior", legend=false, grid=false, framestyle=:box,
        xrotation=45)

    # Overlay posterior density
    density!(plt, samples;
        fill=true, fillalpha=0.4, color=:steelblue, linewidth=2,
        label="Posterior")

    # Add median and CI lines
    vline!(plt, [med]; color=:red, linewidth=2, linestyle=:solid, label="")
    vline!(plt, [ci_lo, ci_hi]; color=:red, linewidth=1, linestyle=:dash, label="")

    push!(plots, plt)
end

p = plot(plots...; layout=(7, 3), size=(1200, 1000), margin=8mm)
savefig(p, "posterior_marginals.png")
println("Saved: posterior_marginals.png")

